#include "poly.hpp"
std::string expression(const Algebra::Poly&p){if(p.empty())return "0";std::string s;for(auto&[m,c]:p){if(!s.empty())s+="+";s+=std::to_string(c);if(m.x)s+="*x^"+std::to_string(m.x);if(m.y)s+="*y^"+std::to_string(m.y);}return s;}
Algebra::Poly from_wire(const json&j){Algebra::Poly p;for(auto&t:j)Algebra::term(p,{t[0].get<int>(),t[1].get<int>()},val(t[2]));return p;}
int main(int argc,char**argv){try{need(argc==2,"ROOT");std::string root=argv[1];auto family=load(root+"/data/family.json"),bases=load(root+"/data/ic_factorbases.json");std::ofstream out(root+"/validation/singular_all.sing");out<<"ring r=(integer,"<<PRIME<<"),(x,y),dp;\npoly F,G,H; ideal I,E,A,B; int failures=0;\n";U count=0;for(int cid=0;cid<46;cid++){std::ifstream in(root+"/runs/ic/curve_"+std::to_string(cid)+".jsonl");need(bool(in),"IC journal missing");std::string line;while(std::getline(in,line)){auto row=json::parse(line);int g=row["generator"];std::vector<Point>b;for(auto&p:bases[std::to_string(cid)][g])b.push_back(point(p));Point R=point(row["R"]);auto f=Algebra::f3(R.x,val(family["nodes"][cid]["a"]),val(family["nodes"][cid]["b"])),gx=Algebra::factor_poly(b,false),gy=Algebra::factor_poly(b,true);out<<"F="<<expression(f)<<";G="<<expression(gx)<<";H="<<expression(gy)<<";I=F,G,H;E=";bool first=true;for(auto&p:row["gb_basis"]){if(!first)out<<",";first=false;out<<expression(from_wire(p));}out<<";A=std(I);B=std(E);if(size(reduce(A,B))!=0 || size(reduce(B,A))!=0){failures++;print(\"FAIL "<<count<<"\");}else{print(\"PASS "<<count<<"\");}\n";count++;}}out<<"print(\"TOTAL "<<count<<"\");print(\"FAILURES \"+string(failures));quit;\n";out.close();save(root+"/validation/singular_export.json",{{"systems",count},{"includes_expected_or_recovered_scalars",false},{"comparisons","Independent std() and both ideal containments"}});std::cout<<count<<" systems exported without scalar witnesses\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
